package webui

import (
	"fmt"
	"math"
	"regexp"
	"strconv"
	"strings"
	"testing"
)

// Contrast guard for the six palettes (three themes × light / dark) generated by
// scripts/gen-themes.py. Each rule is a foreground / background pair the UI really draws, with
// the WCAG 2 minimum: 4.5:1 for text, 3:1 for icons and other non-text marks (1.4.3 / 1.4.11).
// Semi-transparent tiles are composited over the surface they sit on before measuring, the same
// way primer/primitives' scripts/colorContrast.ts flattens alpha colours.

type rgb [3]float64

func parseHex(s string) (rgb, bool) {
	s = strings.TrimPrefix(strings.TrimSpace(s), "#")
	if len(s) != 6 {
		return rgb{}, false
	}
	var c rgb
	for i := 0; i < 3; i++ {
		v, err := strconv.ParseUint(s[2*i:2*i+2], 16, 8)
		if err != nil {
			return rgb{}, false
		}
		c[i] = float64(v)
	}
	return c, true
}

func (c rgb) hex() string {
	return fmt.Sprintf("#%02x%02x%02x", int(math.Round(c[0])), int(math.Round(c[1])), int(math.Round(c[2])))
}

func relLum(c rgb) float64 {
	var l [3]float64
	for i, v := range c {
		v /= 255
		if v <= 0.04045 {
			l[i] = v / 12.92
		} else {
			l[i] = math.Pow((v+0.055)/1.055, 2.4)
		}
	}
	return 0.2126*l[0] + 0.7152*l[1] + 0.0722*l[2]
}

func contrastRatio(a, b rgb) float64 {
	la, lb := relLum(a), relLum(b)
	if la < lb {
		la, lb = lb, la
	}
	return (la + 0.05) / (lb + 0.05)
}

// over composites fg at alpha a onto an opaque bg.
func over(fg rgb, a float64, bg rgb) rgb {
	var c rgb
	for i := range c {
		c[i] = fg[i]*a + bg[i]*(1-a)
	}
	return c
}

var rgbaRe = regexp.MustCompile(`^rgba\((\d+), (\d+), (\d+), ([0-9.]+)\)$`)

// palette holds the opaque colours of one theme block; alpha holds rgba() tiles.
type palette struct {
	col   map[string]rgb
	alpha map[string]float64
}

var declRe = regexp.MustCompile(`--([a-z0-9-]+): ([^;]+);`)

func themeBlocks(t *testing.T) map[string]palette {
	t.Helper()
	raw, err := Static.ReadFile("static/styles.css")
	if err != nil {
		t.Fatal(err)
	}
	css := strings.ReplaceAll(string(raw), "\r\n", "\n")
	out := map[string]palette{}
	for _, th := range []string{"graphite", "tide", "midnight"} {
		light := fmt.Sprintf("\nhtml[data-theme=%q] {\n", th)
		if th == "graphite" {
			light = "\n:root, html[data-theme=\"graphite\"] {\n"
		}
		dark := fmt.Sprintf("\nhtml[data-theme=%q][data-mode=\"dark\"]", th)
		for mode, sel := range map[string]string{"light": light, "dark": dark} {
			i := strings.Index(css, sel)
			if i < 0 {
				t.Fatalf("%s %s: block not found", th, mode)
			}
			body := css[i+len(sel):]
			body = body[strings.Index(body, "{")+1:]
			body = body[:strings.Index(body, "\n}")]
			p := palette{col: map[string]rgb{}, alpha: map[string]float64{}}
			for _, m := range declRe.FindAllStringSubmatch(body, -1) {
				if c, ok := parseHex(m[2]); ok {
					p.col[m[1]] = c
				} else if r := rgbaRe.FindStringSubmatch(m[2]); r != nil {
					var c rgb
					for k := 0; k < 3; k++ {
						v, _ := strconv.Atoi(r[k+1])
						c[k] = float64(v)
					}
					a, _ := strconv.ParseFloat(r[4], 64)
					p.col[m[1]] = c
					p.alpha[m[1]] = a
				}
			}
			out[th+" "+mode] = p
		}
	}
	return out
}

type cpair struct {
	fg, bg string
	min    float64
}

var (
	surfaces = []string{"bg", "bg-sunk", "surface", "surface-2", "row-hover"}
	hueNames = []string{"blue", "teal", "violet", "pink", "orange", "red", "green", "cyan", "amber", "slate", "indigo"}
)

func contrastRules() []cpair {
	var r []cpair
	text := func(fg string, bgs ...string) {
		for _, b := range bgs {
			r = append(r, cpair{fg, b, 4.5})
		}
	}
	for _, fg := range []string{"text", "text-2", "text-3"} {
		text(fg, append(surfaces, "accent-50", "code-bg")...)
	}
	text("accent", append(surfaces, "accent-50")...) // links, current items
	for _, s := range []string{"ok", "warn", "danger", "info"} {
		text(s, append(surfaces, s+"-50")...) // status text, pills on their tint
	}
	text("accent-fg", "accent", "accent-600")
	text("primary-fg", "primary-bg", "primary-hover")
	text("on-fill", "danger", "ok", "hue-violet") // danger button, finished step, avatar
	text("tip-fg", "tip-bg", "danger")            // tooltips, toasts, failed toast
	text("tip-link", "tip-bg")
	text("side-fg", "side-bg", "side-hover")
	text("side-active-fg", "side-active-bg")
	text("text", "mark-bg", "mark-cur")
	for _, h := range hueNames {
		// coloured icons: non-text, 3:1 wherever they are drawn (rows, sidebar, active nav item)
		for _, b := range append(surfaces, "side-bg", "side-hover", "side-active-bg") {
			r = append(r, cpair{"hue-" + h, b, 3})
		}
		r = append(r, cpair{"hue-" + h, "tile:hue-" + h + "-bg", 3})
		// tag / chip text on its own tile, over every surface it can sit on
		for _, b := range []string{"bg", "bg-sunk", "surface", "surface-2"} {
			r = append(r, cpair{"hue-" + h + "-fg", "tile:hue-" + h + "-bg@" + b, 4.5})
		}
	}
	return r
}

func (p palette) resolve(t *testing.T, where, name string) rgb {
	t.Helper()
	if strings.HasPrefix(name, "tile:") {
		name = strings.TrimPrefix(name, "tile:")
		under := "surface"
		if i := strings.IndexByte(name, '@'); i >= 0 {
			name, under = name[:i], name[i+1:]
		}
		a, ok := p.alpha[name]
		if !ok {
			t.Fatalf("%s: --%s is not an rgba() tile", where, name)
		}
		return over(p.col[name], a, p.resolve(t, where, under))
	}
	c, ok := p.col[name]
	if !ok {
		t.Fatalf("%s: no --%s colour", where, name)
	}
	if _, isTile := p.alpha[name]; isTile {
		t.Fatalf("%s: --%s is translucent; measure it as a tile", where, name)
	}
	return c
}

func TestThemeContrast(t *testing.T) {
	blocks := themeBlocks(t)
	if len(blocks) != 6 {
		t.Fatalf("want 6 palettes, got %d", len(blocks))
	}
	rules := contrastRules()
	for where, p := range blocks {
		fails := 0
		for _, r := range rules {
			fg, bg := p.resolve(t, where, r.fg), p.resolve(t, where, r.bg)
			if got := contrastRatio(fg, bg); got < r.min {
				fails++
				t.Errorf("%s: --%s %s on %s %s is %.2f:1, needs %.1f:1", where, r.fg, fg.hex(), r.bg, bg.hex(), got, r.min)
			}
		}
		if fails == 0 {
			t.Logf("%s: %d pairs pass", where, len(rules))
		}
	}
}

func TestContrastMath(t *testing.T) {
	w, _ := parseHex("#ffffff")
	k, _ := parseHex("#000000")
	if got := contrastRatio(w, k); math.Abs(got-21) > 1e-9 {
		t.Fatalf("white/black = %v", got)
	}
	g, _ := parseHex("#767676") // the classic grey that just passes AA on white
	if got := contrastRatio(g, w); got < 4.5 || got > 4.6 {
		t.Fatalf("#767676 on white = %.3f", got)
	}
	if c := over(k, 0.5, w).hex(); c != "#808080" {
		t.Fatalf("50%% black over white = %s", c)
	}
}

// Text on hue tiles and solid fills must use the derived inks, not the icon hue or a literal white.
func TestContrastInksUsed(t *testing.T) {
	raw, err := Static.ReadFile("static/styles.css")
	if err != nil {
		t.Fatal(err)
	}
	css := strings.ReplaceAll(string(raw), "\r\n", "\n")
	// Icon tiles (selectors naming an .ico) may use the plain hue: icons need 3:1, not 4.5:1.
	for _, m := range regexp.MustCompile(`(?m)^([^{}\n]+)\{[^}]*background: var\(--hue-[a-z]+-bg\);[^}]*\bcolor: var\(--hue-[a-z]+\);`).FindAllStringSubmatch(css, -1) {
		if !strings.Contains(m[1], "ico") {
			t.Errorf("text on a hue tile uses the icon hue instead of --hue-*-fg: %q", m[0])
		}
	}
	if m := regexp.MustCompile(`background: var\(--(danger|ok|warn|info|hue-[a-z]+)\);[^}]*\bcolor: #fff`).FindString(css); m != "" {
		t.Errorf("white text on a theme fill (unreadable in dark palettes): %q", m)
	}
	for _, s := range []string{
		".btn.danger-solid { background: var(--danger); color: var(--on-fill);",
		".ttag.h0 { background: var(--hue-blue-bg); color: var(--hue-blue-fg);",
		".log .tool-chip", "color: var(--hue-violet-fg); margin-right: 8px;",
	} {
		if !strings.Contains(css, s) {
			t.Errorf("styles.css lacks %q", s)
		}
	}
}
